namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings == 0 ? 0 : (double)RatingSum / TotalRatings;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;
    private readonly object _lock = new();

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1,
                Title = "Classic Pancakes",
                Category = "Breakfast",
                Description = "Fluffy buttermilk pancakes perfect for a weekend morning.",
                Ingredients = ["2 cups all-purpose flour", "2 tablespoons sugar", "1 tablespoon baking powder", "1/2 teaspoon salt", "2 eggs", "1 3/4 cups buttermilk", "1/4 cup melted butter"],
                Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, buttermilk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Pour 1/4 cup batter onto a hot greased griddle.", "Cook until bubbles form on top, then flip and cook until golden."],
                TotalRatings = 5,
                RatingSum = 22
            },
            new Recipe
            {
                Id = 2,
                Title = "Avocado Toast",
                Category = "Breakfast",
                Description = "Simple and delicious avocado toast with a hint of lemon.",
                Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tablespoon lemon juice", "Salt and pepper to taste", "Red pepper flakes", "1 tablespoon olive oil"],
                Steps = ["Toast the sourdough slices until golden.", "Mash the avocado with lemon juice, salt, and pepper.", "Spread the avocado mixture onto the toast.", "Drizzle with olive oil and sprinkle red pepper flakes."],
                TotalRatings = 3,
                RatingSum = 13
            },
            new Recipe
            {
                Id = 3,
                Title = "Spaghetti Bolognese",
                Category = "Main Course",
                Description = "A rich and hearty Italian meat sauce served over spaghetti.",
                Ingredients = ["1 pound spaghetti", "1 pound ground beef", "1 onion, diced", "3 cloves garlic, minced", "1 can (28 oz) crushed tomatoes", "2 tablespoons tomato paste", "1 teaspoon dried oregano", "1 teaspoon dried basil", "Salt and pepper to taste", "Parmesan cheese for serving"],
                Steps = ["Cook spaghetti according to package directions.", "Brown ground beef in a large skillet, then drain.", "Sauté onion and garlic until softened.", "Add crushed tomatoes, tomato paste, oregano, and basil.", "Simmer for 20 minutes, stirring occasionally.", "Season with salt and pepper, serve over spaghetti with Parmesan."],
                TotalRatings = 8,
                RatingSum = 35
            },
            new Recipe
            {
                Id = 4,
                Title = "Grilled Chicken Caesar Salad",
                Category = "Main Course",
                Description = "Crisp romaine lettuce with grilled chicken and creamy Caesar dressing.",
                Ingredients = ["2 chicken breasts", "1 head romaine lettuce", "1/2 cup Caesar dressing", "1/2 cup croutons", "1/4 cup shaved Parmesan", "1 tablespoon olive oil", "Salt and pepper"],
                Steps = ["Season chicken with olive oil, salt, and pepper.", "Grill chicken over medium-high heat for 6-7 minutes per side.", "Let chicken rest 5 minutes, then slice.", "Chop romaine and toss with Caesar dressing.", "Top with sliced chicken, croutons, and Parmesan."],
                TotalRatings = 4,
                RatingSum = 18
            },
            new Recipe
            {
                Id = 5,
                Title = "Chocolate Lava Cake",
                Category = "Desserts",
                Description = "Decadent individual chocolate cakes with a molten center.",
                Ingredients = ["4 oz dark chocolate", "1/2 cup butter", "1 cup powdered sugar", "2 eggs", "2 egg yolks", "6 tablespoons flour", "Butter and cocoa for ramekins"],
                Steps = ["Preheat oven to 425°F. Grease ramekins with butter and dust with cocoa.", "Melt chocolate and butter together in a microwave or double boiler.", "Stir in powdered sugar until smooth.", "Whisk in eggs and egg yolks, then fold in flour.", "Divide batter among ramekins.", "Bake for 12-14 minutes until edges are firm but center is soft.", "Invert onto plates and serve immediately."],
                TotalRatings = 6,
                RatingSum = 28
            },
            new Recipe
            {
                Id = 6,
                Title = "Strawberry Shortcake",
                Category = "Desserts",
                Description = "Light and fluffy shortcakes topped with fresh strawberries and whipped cream.",
                Ingredients = ["2 cups all-purpose flour", "1/3 cup sugar", "1 tablespoon baking powder", "1/2 teaspoon salt", "6 tablespoons cold butter", "3/4 cup heavy cream", "1 pound fresh strawberries, sliced", "Whipped cream for topping"],
                Steps = ["Preheat oven to 400°F.", "Mix flour, sugar, baking powder, and salt.", "Cut in cold butter until mixture resembles coarse crumbs.", "Stir in cream until dough forms.", "Pat dough to 1-inch thickness and cut into rounds.", "Bake 12-15 minutes until golden.", "Split shortcakes, layer with strawberries and whipped cream."],
                TotalRatings = 4,
                RatingSum = 17
            }
        ];
        _nextId = 7;
    }

    public List<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().ToList();
        }
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetRecipe(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null)
            {
                recipe.TotalRatings++;
                recipe.RatingSum += stars;
            }
        }
    }

    public Recipe SubmitRecipe(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Id = _nextId++;
            _recipes.Add(recipe);
            return recipe;
        }
    }
}

