arguments.file_text:
@page "/categories"
@inject RecipeService RecipeService

<PageTitle>Browse Categories</PageTitle>

<h1>Recipe Categories</h1>
<p>Choose a category to explore recipes.</p>

<ul class="list-group">
    @foreach (var category in RecipeService.GetCategories())
    {
        <li class="list-group-item">
            <a href="category/@category">@category</a>
        </li>
    }
</ul>

@page "/category/{CategoryName}"
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<h1>@CategoryName</h1>

@{
    var recipes = RecipeService.GetRecipesByCategory(CategoryName);
}

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="list-group">
        @foreach (var recipe in recipes)
        {
            <a href="recipe/@recipe.Id" class="list-group-item list-group-item-action">
                <div class="d-flex w-100 justify-content-between">
                    <h5 class="mb-1">@recipe.Title</h5>
                    <small>⭐ @recipe.AverageRating.ToString("F1")</small>
                </div>
                <p class="mb-1">@recipe.Description</p>
            </a>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;
}

@page "/recipe/{Id:int}"
@inject RecipeService RecipeService

@{
    var recipe = RecipeService.GetRecipe(Id);
}

@if (recipe is null)
{
    <PageTitle>Recipe Not Found</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <PageTitle>@recipe.Title</PageTitle>

    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: <a href="category/@recipe.Category">@recipe.Category</a></p>
    <p>@recipe.Description</p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li>@step</li>
        }
    </ol>

    <h3>Rate this Recipe</h3>
    <StarRating RecipeId="@Id" />
}

@code {
    [Parameter]
    public int Id { get; set; }
}

@rendermode InteractiveServer
@inject RecipeService RecipeService

@if (_hasRated)
{
    <p style="color: green; font-weight: bold;">Thanks for rating!</p>
    <p>Average rating: ⭐ @_averageRating.ToString("F1")</p>
}
else
{
    <div>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button @onclick="() => SubmitRating(star)"
                    style="background: none; border: none; cursor: pointer; font-size: 1.5rem; color: @(star <= _hoverStar ? "gold" : "gray");"
                    @onmouseover="() => _hoverStar = star"
                    @onmouseout="() => _hoverStar = 0"
                    title="@star star(s)">
                @(star <= _hoverStar ? "★" : "☆")
            </button>
        }
    </div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private bool _hasRated;
    private double _averageRating;
    private int _hoverStar;

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipe(RecipeId);
        _averageRating = recipe?.AverageRating ?? 0;
        _hasRated = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <p>Your recipe "<strong>@_submittedRecipe!.Title</strong>" has been submitted!</p>
        <a href="recipe/@_submittedRecipe.Id">View your recipe</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="mb-3">
            <label for="title" class="form-label">Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label for="description" class="form-label">Description</label>
            <InputTextArea id="description" class="form-control" @bind-Value="_model.Description" rows="2" />
            <ValidationMessage For="() => _model.Description" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" @bind-Value="_model.Ingredients" rows="5" />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" @bind-Value="_model.Steps" rows="5" />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private Recipe? _submittedRecipe;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = _model.Title,
            Category = _model.Category,
            Description = _model.Description,
            Ingredients = _model.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = _model.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };

        _submittedRecipe = RecipeService.SubmitRecipe(recipe);
        _submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required.")]
        public string Category { get; set; } = string.Empty;

        public string Description { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "At least one ingredient is required.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "At least one step is required.")]
        public string Steps { get; set; } = string.Empty;
    }
}

